  SpellIds.seeInvisibility: SpellDefinition(
    id: SpellIds.seeInvisibility,
    content: RuleContent(
      id: SpellIds.seeInvisibility,
      name: 'Vedere Invisibilità',
      type: RuleContentType.spell,
      description: RuleDescription(
        summary:
